// launch. Four things are set at launch and nowhere else: RUN (which run this
// is: 'first' is batch 7, rungs H and A; 'second' is batch 7b, rungs S, C, W
// and L; 'all' is the six as one batch 7; the record's section 1, "Two runs of
// one record"), LEDGER_FROM (the first free ledger row at this run's launch;
// the block refuses to load while it is unset), H_RIDES (false if batch 6
// landed without the errors rung H repairs), and P1_COUNT (each rung's
// predicted checker total, from probe P1 and the base's landed table;
// undefined declares none). Manifest order is the ledger numbering order: H, A
// in the first run, S, C, W, L in the second, S, C, W, L, H, A as one run; the
// scatter starts the longest expected first (A, H; L, W, C, S; L, A, W, C, H,
// S). No rung declares a ladder move. The base is <base>, passed at launch as
// args.base, not written here.
// ===========================================================================

const RUN = 'first'     // SET AT LAUNCH: 'first' (batch 7: H and A), 'second' (batch 7b: S, C, W, L) or 'all' (the six as one batch 7); the record's section 1, "Two runs of one record"
const H_RIDES = true    // the record's section 1: rung H rides if the landed table still shows the 19 errors of its section 3; false drops it
const LEDGER_FROM = null   // SET AT LAUNCH: one above the highest row of explorations/fortress-gap-ledger.md at this run's launch
if (!Number.isInteger(LEDGER_FROM)) throw new Error('LEDGER_FROM is not set: the first free ledger row at this run\'s launch')
const P1_COUNT = { S: undefined, C: undefined, W: undefined, L: undefined, H: undefined, A: undefined }   // SET AT LAUNCH from probe P1

if (!['first', 'second', 'all'].includes(RUN)) throw new Error('RUN is not one of first, second, all')
const BATCH = RUN === 'second' ? '7b' : '7'
const BATCH_RECORD = 'explorations/coordinator/CLIMB-BATCH-7.md'

const S_TAIL = [
